SELECT * FROM quality_rows
quality_status = #{status}
AND (question_content ILIKE '%' || #{keyword} || '%' OR passage_title ILIKE '%' || #{keyword} || '%' OR topic ILIKE '%' || #{keyword} || '%')
ORDER BY CASE quality_status WHEN 'REVIEW_REQUIRED' THEN 1 WHEN 'DATA_INSUFFICIENT' THEN 2 ELSE 3 END, challenge_date DESC, question_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM quality_rows
quality_status = #{status}
AND (question_content ILIKE '%' || #{keyword} || '%' OR passage_title ILIKE '%' || #{keyword} || '%' OR topic ILIKE '%' || #{keyword} || '%')

SELECT qo.id AS option_id, qo.question_id, qo.position, qo.content, COUNT(aa.selected_option_id) AS selected_count, CASE WHEN COALESCE(totals.response_count, 0) = 0 THEN 0 ELSE ROUND(COUNT(aa.selected_option_id) * 100.0 / totals.response_count, 1) END AS selection_rate, qo.id = qk.correct_option_id AS correct FROM question_options qo JOIN question_keys qk ON qk.question_id = qo.question_id LEFT JOIN attempt_answers aa ON aa.selected_option_id = qo.id LEFT JOIN ( SELECT question_id, COUNT(*) AS response_count FROM attempt_answers GROUP BY question_id ) totals ON totals.question_id = qo.question_id WHERE qo.question_id IN
#{questionId}
GROUP BY qo.id, qo.question_id, qo.position, qo.content, qk.correct_option_id, totals.response_count ORDER BY qo.question_id, qo.position
